//Turns off Function ID and Library Identification analysis before
//auto-analysis whilst running headless Ghidra for import and ingest
//of programs (object files/libraries) for use in creating FID libraries
//@category FunctionID


using ghidra.app.script;

public class FunctionIDHeadlessPrescript : GhidraScript {
	// must turn off FID and LID when analyzing libraries for FID
	// creation, in order to avoid corrupting names

	// also, it's important that your loaders have moved object file
	// sections to an appropriate height above 0x0 in order for the
	// scalar operand analyzer to run; we need to identify those
	// references to rule out scalar addresses!

	private static readonly string FUNCTION_ID_ANALYZER = "Function ID";
	private static readonly string LIBRARY_IDENTIFICATION = "Library Identification";
	private static readonly string DEMANGLER_MS_ANALYZER = "Demangler Microsoft";
	private static readonly string DEMANGLER_GNU_ANALYZER = "Demangler GNU";
	private static readonly string DEMANGLER_RUST_ANALYZER = "Demangler Rust";
	private static readonly string DEMANGLER_SWIFT_ANALYZER = "Demangler Swift";
	private static readonly string SCALAR_OPERAND_ANALYZER = "Scalar Operand References";

	/* @Override */
	protected void run()
    {
		Map<string, string> options = getCurrentAnalysisOptionsAndValues(currentProgram);
		if (options.containsKey(FUNCTION_ID_ANALYZER)) {
			setAnalysisOption(currentProgram, FUNCTION_ID_ANALYZER, "false");
		}
		if (options.containsKey(LIBRARY_IDENTIFICATION)) {
			setAnalysisOption(currentProgram, LIBRARY_IDENTIFICATION, "false");
		}
		if (options.containsKey(DEMANGLER_MS_ANALYZER)) {
			setAnalysisOption(currentProgram, DEMANGLER_MS_ANALYZER, "false");
		}
		if (options.containsKey(DEMANGLER_GNU_ANALYZER)) {
			setAnalysisOption(currentProgram, DEMANGLER_GNU_ANALYZER, "false");
		}
		if (options.containsKey(DEMANGLER_RUST_ANALYZER)) {
			setAnalysisOption(currentProgram, DEMANGLER_RUST_ANALYZER, "false");
		}
		if (options.containsKey(DEMANGLER_SWIFT_ANALYZER)) {
			setAnalysisOption(currentProgram, DEMANGLER_SWIFT_ANALYZER, "false");
		}
		if (options.containsKey(SCALAR_OPERAND_ANALYZER)) {
			setAnalysisOption(currentProgram, SCALAR_OPERAND_ANALYZER, "true");
		}
	}
}
